import React from 'react';

export type GlyphIconSize = 'tiny' | 'small' | 'medium' | 'large' | 'xlarge';

export interface LocalIconProps extends Omit<
  React.SVGProps<SVGSVGElement>,
  'size' | 'width' | 'height'
> {
  size?: GlyphIconSize | number;
}

export interface SvgPathDefinition {
  clipRule?: React.SVGProps<SVGPathElement>['clipRule'];
  d: string;
  fill?: React.SVGProps<SVGPathElement>['fill'];
  fillRule?: React.SVGProps<SVGPathElement>['fillRule'];
}

export interface SvgIconDefinition {
  paths: readonly SvgPathDefinition[];
  viewBox: string;
}

export const glyphIconPixelSizes: Record<GlyphIconSize, number> = {
  tiny: 12,
  small: 16,
  medium: 16,
  large: 24,
  xlarge: 32,
};

export function resolveIconSize(size: LocalIconProps['size'] = 'large') {
  return typeof size === 'string' && size in glyphIconPixelSizes
    ? glyphIconPixelSizes[size as GlyphIconSize]
    : size;
}

export function createSvgIconComponent(
  displayName: string,
  definition: SvgIconDefinition,
) {
  const SvgIcon = React.forwardRef<SVGSVGElement, LocalIconProps>(
    ({ size = 'large', ...props }, forwardedRef) => {
      const hasAccessibleName = Boolean(
        props['aria-label'] || props['aria-labelledby'],
      );
      const resolvedSize = resolveIconSize(size);

      return (
        <svg
          {...props}
          ref={forwardedRef}
          width={resolvedSize}
          height={resolvedSize}
          fill="none"
          viewBox={definition.viewBox}
          aria-hidden={props['aria-hidden'] ?? !hasAccessibleName}
          focusable="false"
          xmlns="http://www.w3.org/2000/svg"
        >
          {definition.paths.map((path, index) => (
            <path key={`${displayName}-${index}`} {...path} />
          ))}
        </svg>
      );
    },
  );

  SvgIcon.displayName = displayName;

  return SvgIcon;
}
